package io.github.jesterportfolio.hearth.survival.rpg;

import java.util.*;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.inventory.*;import org.bukkit.event.*;import org.bukkit.event.inventory.*;
import net.kyori.adventure.text.Component;
import io.github.jesterportfolio.hearth.economy.RpgStore;

/** 커스텀 팩 없이 읽을 수 있는 단일 경제 메뉴. token과 정책 세대에 화면을 묶는다. */
public final class RpgMenu implements Listener,AutoCloseable {
    private final RpgRuntime r;private boolean closed;
    public RpgMenu(RpgRuntime r){this.r=r;Bukkit.getPluginManager().registerEvents(this,r.plugin);}
    private final class Screen implements InventoryHolder {final Player player;final Object token;final long generation;final Inventory inventory;final Map<Integer,Runnable> actions=new HashMap<>();Screen(Player p,String title,int size){player=p;token=r.runtime.sessionToken(p);generation=r.generation();inventory=Bukkit.createInventory(this,size,Component.text(title));}public Inventory getInventory(){return inventory;}}
    private boolean current(Screen s){return !closed&&r.available(s.player)&&r.runtime.current(s.player,s.token)&&s.generation==r.generation()&&s.player.getOpenInventory().getTopInventory()==s.inventory;}
    private void button(Screen screen,int slot,Material material,String label,List<String> lore,Runnable action){var item=new ItemStack(material);item.editMeta(meta->{meta.displayName(Component.text(label));meta.lore(lore.stream().map(Component::text).toList());});screen.inventory.setItem(slot,item);if(action!=null)screen.actions.put(slot,action);}
    public void main(Player p){var s=new Screen(p,"경제 서버 · 내 정보와 편의",27);button(s,10,Material.EXPERIENCE_BOTTLE,"숙련도·능력치",List.of("레벨·경험치·마나·스탯 확인"),()->skills(p));button(s,12,Material.COMPASS,"Home으로 이동",List.of("전투·월드 조건과 개인 거주 권한을 확인합니다."),()->r.home(p));button(s,13,Material.RED_BED,"현재 위치를 Home으로 저장",List.of("안전한 등록 월드의 현재 위치"),()->r.setHome(p));button(s,14,Material.IRON_SWORD,"내 개인 거주 PvP 설정",List.of("소유자만 변경할 수 있습니다."),()->r.togglePvp(p));button(s,16,Material.CHEST,"바라보는 오브젝트 보호",List.of("전체 공개·지정 사용자·비공개"),()->object(p,r.objects.selection(p)));p.openInventory(s.inventory);}
    public void skills(Player p){var user=r.aura.api.getUser(p.getUniqueId());if(!user.isLoaded())return;var s=new Screen(p,"숙련도 · 능력치",54);int slot=0;for(var skill:r.aura.api.getGlobalRegistry().getSkills()){if(!skill.isEnabled()||slot>=43)continue;String id=skill.getId().toString();var custom=r.aura.custom.values().stream().filter(c->c.skill().getId().equals(skill.getId())).findFirst();List<String> lore=new ArrayList<>(List.of("레벨 "+user.getSkillLevel(skill),"현재 경험치 "+String.format(Locale.ROOT,"%.1f",user.getSkillXp(skill))));custom.ifPresent(c->lore.add("클릭: 액티브 스킬 사용"));button(s,slot++,Material.EXPERIENCE_BOTTLE,skill.getDisplayName(user.getLocale()),lore,custom.isPresent()?()->r.activate(p,id.substring(id.indexOf('/')+1)):null);}
        button(s,45,Material.NETHER_STAR,"스탯·특성",List.of("AuraSkills와 장비의 최종 능력치"),()->stats(p));button(s,47,Material.LAPIS_LAZULI,"마나 "+String.format(Locale.ROOT,"%.1f",user.getMana()),List.of("액티브 스킬은 마나·PG 쿨다운을 함께 확인합니다."),null);button(s,49,Material.SHIELD,"현재 월드",List.of("PvP "+(r.pvp(p.getWorld())?"허용":"금지"),"사망 정책 "+(r.policy.ready(r.role(p.getWorld()))?"준비됨":"설정 대기"),"고레벨 보상 감소 "+(r.aura.penalized(p.getUniqueId())?"적용":"미적용")),null);button(s,53,Material.OAK_DOOR,"이전 메뉴",List.of(),()->main(p));p.openInventory(s.inventory);}
    private void stats(Player p){var user=r.aura.api.getUser(p.getUniqueId());var s=new Screen(p,"최종 스탯·특성",54);int slot=0;for(var stat:r.aura.api.getGlobalRegistry().getStats()){if(!stat.isEnabled()||slot>=45)continue;button(s,slot++,Material.IRON_CHESTPLATE,stat.getDisplayName(user.getLocale()),List.of("최종 값 "+String.format(Locale.ROOT,"%.2f",user.getStatLevel(stat))),null);}button(s,49,Material.OAK_DOOR,"숙련도",List.of(),()->skills(p));p.openInventory(s.inventory);}
    public void object(Player p,RpgStore.Acl row){var s=new Screen(p,"오브젝트 공개 범위",27);button(s,10,Material.REDSTONE,"비공개 · 소유자",List.of("타인의 보관함/시설 사용 차단"),()->r.objects.mode(p,row,RpgStore.Mode.PRIVATE));button(s,12,Material.PLAYER_HEAD,"지정 사용자",List.of("/보호 허용 <접속 사용자>","현재 허용 "+row.allowed().size()+"명","건축 권한은 주지 않습니다."),()->r.objects.mode(p,row,RpgStore.Mode.LIST));button(s,14,Material.EMERALD,"전체 공개",List.of("누구나 사용·자동 이동 가능"),()->r.objects.mode(p,row,RpgStore.Mode.PUBLIC));button(s,16,Material.BARRIER,"보호 해제",List.of("소유 구획의 기본 WG 권한으로 돌아갑니다."),()->r.objects.mode(p,row,RpgStore.Mode.REMOVED));p.openInventory(s.inventory);}
    @EventHandler(priority=EventPriority.HIGHEST) public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof RpgMenu.Screen s))return;boolean denied=e.isCancelled();e.setCancelled(true);if(denied||e.getWhoClicked()!=s.player||!current(s)||e.getClickedInventory()!=s.inventory||e.getClick()!=ClickType.LEFT||!s.player.getItemOnCursor().isEmpty())return;var action=s.actions.get(e.getSlot());if(action!=null)Bukkit.getScheduler().runTask(r.plugin,()->{if(current(s))try{action.run();}catch(Exception error){s.player.sendMessage(Component.text("대상·권한·안전 위치를 다시 확인해 주세요."));}});}
    @EventHandler(priority=EventPriority.HIGHEST) public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof RpgMenu.Screen)e.setCancelled(true);}
    public void close(){closed=true;HandlerList.unregisterAll(this);}
}
